"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import { DiagramFrame, StageNode } from "@diax/ui-react/presentation";
import type { DiaxRelation } from "diax";
import { Eye, ShieldCheck, TrendingUp } from "lucide-react";
import type { ReactNode } from "react";

const phases = [
  {
    id: "observe",
    step: "01 / Observe",
    title: "Instrument without blocking",
    description: "Establish a trustworthy baseline before changing developer behavior.",
    status: "complete" as const,
    tone: "info" as const,
    owner: "Platform observability",
    metric: "100%",
    metricLabel: "workflows reporting",
    actions: ["Run checks in advisory mode", "Capture edge cases", "Publish a shared baseline"],
  },
  {
    id: "explain",
    step: "02 / Explain",
    title: "Make the evidence visible",
    description: "Turn raw findings into team-level signals people can understand and act on.",
    status: "active" as const,
    tone: "success" as const,
    owner: "Product enablement",
    metric: "4.6×",
    metricLabel: "faster issue discovery",
    actions: [
      "Show trends, not isolated failures",
      "Link every signal to its source",
      "Keep remediation one click away",
    ],
  },
  {
    id: "enforce",
    step: "03 / Enforce",
    title: "Protect the new baseline",
    description: "Block only new regressions after the team has learned the system.",
    status: "upcoming" as const,
    tone: "warning" as const,
    owner: "Repository owners",
    metric: "< 30",
    metricLabel: "known critical findings",
    actions: [
      "Gate incremental risk",
      "Keep legacy debt visible",
      "Provide an automated repair path",
    ],
  },
] as const;

const behaviorShift = [
  { phase: "Observe", mindset: "This does not affect me", behavior: "Passive awareness" },
  { phase: "Explain", mindset: "I can see my project risk", behavior: "Active investigation" },
  { phase: "Enforce", mindset: "I check before I merge", behavior: "Habitual prevention" },
] as const;

const relations: readonly DiaxRelation<ReactNode>[] = [
  {
    id: "observe-explain",
    from: "observe",
    to: "explain",
    color: "#25879a",
    targetMarker: "arrow",
    gap: 8,
    label: <TransitionLabel>Trust the data</TransitionLabel>,
  },
  {
    id: "explain-enforce",
    from: "explain",
    to: "enforce",
    color: "#e8613c",
    targetMarker: "arrow",
    gap: 8,
    label: <TransitionLabel>Protect the habit</TransitionLabel>,
  },
];

export default function ProgressiveRollout() {
  return (
    <DiagramFrame
      data-showcase-corpus="progressive-rollout"
      eyebrow="Adoption strategy · Authored DOM"
      title="Progressive rollout"
      description="Move from observation to enforcement without asking teams to trust a gate they have never seen."
      icon={<TrendingUp aria-hidden="true" />}
      caption="The cards and behavior model remain ordinary semantic DOM. DiaX owns only the 2 measured transitions."
      className="w-full max-w-[1120px] [--diax-frame-bg:#f3f5f6] [--diax-frame-radius:3px] [--diax-frame-shadow:none] [--diax-node-bg:#fff] [--diax-node-border:#c8d0d5] [--diax-node-shadow:none] [--diax-node-text:#18232c] [--diax-ui-radius:3px]"
    >
      <ConnectionSurface
        relations={relations}
        pathType="orthogonal"
        aria-label="Progressive rollout phase transitions"
        className="grid gap-20 py-3 sm:grid-cols-3 sm:gap-12 sm:py-6"
      >
        {phases.map((phase, index) => (
          <StageNode
            key={phase.id}
            {...connectionTarget(phase.id)}
            title={phase.title}
            step={phase.step}
            status={phase.status}
            tone={phase.tone}
            owner={phase.owner}
            description={phase.description}
            icon={index === 1 ? <Eye aria-hidden="true" /> : <ShieldCheck aria-hidden="true" />}
            className="relative h-full max-w-none"
          >
            <ul className="m-0 grid list-none gap-2 p-0 text-[11px] text-slate-600">
              {phase.actions.map((action) => (
                <li key={action} className="grid grid-cols-[10px_minmax(0,1fr)] gap-1.5">
                  <span aria-hidden="true" className="mt-[7px] block size-1 bg-current" />
                  <span>{action}</span>
                </li>
              ))}
            </ul>
            <dl className="mt-3 grid grid-cols-[auto_minmax(0,1fr)] items-baseline gap-2 border-t border-slate-200 pt-3">
              <dd className="m-0 font-mono text-xl font-bold tracking-[-0.05em] text-slate-900">
                {phase.metric}
              </dd>
              <dt className="text-[9px] font-semibold uppercase tracking-[0.08em] text-slate-500">
                {phase.metricLabel}
              </dt>
            </dl>
          </StageNode>
        ))}
      </ConnectionSurface>

      <section
        className="mt-5 border-t border-slate-300 pt-4"
        aria-labelledby="behavior-shift-title"
      >
        <div className="grid gap-1 sm:grid-cols-[180px_minmax(0,1fr)] sm:items-end">
          <h2
            id="behavior-shift-title"
            className="m-0 font-mono text-[10px] font-bold uppercase tracking-[0.12em] text-slate-600"
          >
            Behavior shift
          </h2>
          <p className="m-0 text-[10px] text-slate-500 sm:text-right">
            Enforcement is the outcome of understanding—not the opening move.
          </p>
        </div>
        <ol className="m-0 mt-3 grid list-none border-y border-slate-300 p-0 sm:grid-cols-3">
          {behaviorShift.map((item, index) => (
            <li
              key={item.phase}
              className="grid grid-cols-[32px_minmax(0,1fr)] gap-2 border-slate-300 px-2 py-3 sm:border-l sm:first:border-l-0"
            >
              <span className="font-mono text-[10px] font-bold text-[#25879a]">
                {String(index + 1).padStart(2, "0")}
              </span>
              <span>
                <strong className="block text-[11px] text-slate-900">{item.mindset}</strong>
                <small className="mt-1 block text-[9px] uppercase tracking-[0.06em] text-slate-500">
                  {item.phase} · {item.behavior}
                </small>
              </span>
            </li>
          ))}
        </ol>
      </section>
    </DiagramFrame>
  );
}

function TransitionLabel({ children }: { children: ReactNode }) {
  return (
    <span className="border border-slate-300 bg-[#f3f5f6] px-2 py-1 font-mono text-[9px] font-bold uppercase tracking-[0.06em] text-slate-600">
      {children}
    </span>
  );
}
